<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= tt_h($siteName) ?></title><link rel="stylesheet" href="assets/app.css"><style>:root{--accent:<?= tt_h($accent) ?>}</style></head>
